ids=["LY-426","LY-427","LY-428","LY-429","LY-430","LY-432","LY-433","LY-434","LY-436","LY-437","LY-439","LY-440","LY-441","LY-442","LY-443","LY-445","LY-446","LY-449","LY-451","LY-452"]
assert set(P)==set(ids) and len(P)==20, (set(ids)^set(P), len(P))
for cid in ids:
    d=P[cid]
    assert set(d)== {"case_id","prediction_text","basis","confidence","trigger"}
    assert set(d["trigger"])=={"changed_main","reserve_used","disputed","reason"}
    assert isinstance(d["confidence"], float) and 0<=d["confidence"]<=1
    assert d["basis"].splitlines()[0].strip()
    with open(os.path.join(OUT, cid+".json"),"w",encoding="utf-8") as f:
        json.dump(d,f,ensure_ascii=False,indent=1)
print("written", len(P))
print("changed_main", sum(v["trigger"]["changed_main"] for v in P.values()))
print("reserve_used", sum(v["trigger"]["reserve_used"] for v in P.values()))
print("disputed", sum(v["trigger"]["disputed"] for v in P.values()))
